package com.tencent.weknora.knowledge;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.security.ApiException;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.assertj.core.api.Assertions.*;

/** Actual production Go service/type/utils oracles, not Java-generated expectations. */
class KnowledgeProcessCompatibilityTest {
    private final ObjectMapper json=new ObjectMapper();private final KnowledgeProcessConfig config=new KnowledgeProcessConfig(json);
    JsonNode fixture(String name)throws Exception{try(var input=getClass().getResourceAsStream("/"+name)){return json.readTree(input);}}
    @Test void productionGoEffectiveConfigMatchesEveryMergedField()throws Exception{for(var row:fixture("go-knowledge-process.json")){JsonNode actual=json.readTree(json.writeValueAsBytes(config.resolve(row.get("kb"),row.get("overrides"))));assertThat(actual).as("KB=%s overrides=%s",row.path("kb"),row.path("overrides")).isEqualTo(row.path("effective"));}}
    @Test void productionGoUploadOverrideValidationMatchesImageAudioAndUnicodePromptGates()throws Exception{for(var row:fixture("go-knowledge-process-validation.json").path("validation")){List<String> types=new ArrayList<>();for(var type:row.path("file_types"))types.add(type.asText());String message="";int code=0;try{config.validateProcessOverrides(row.get("kb"),row.get("overrides"),types);}catch(ApiException ex){message=ex.getMessage();code=ex.appCode();assertThat(ex.status()).isEqualTo(400);}assertThat(message).as("validation %s",row).isEqualTo(row.path("error").asText());assertThat(code).isEqualTo(row.path("code").asInt());}}
    @Test void productionGoFolderNamesByteBudgetsAndInputValidationMatch()throws Exception{for(var row:fixture("go-knowledge-process-validation.json").path("names")){String name=row.path("name").asText();var path=KnowledgeImportNames.split(name);var safe=KnowledgeImportNames.validate(name);assertThat(path.folder()).as(name).isEqualTo(row.path("folder").asText());assertThat(path.filename()).as(name).isEqualTo(row.path("file").asText());assertThat(KnowledgeImportNames.normalizeFolder(name)).as(name).isEqualTo(row.path("normalized").asText());assertThat(safe.value()).as(name).isEqualTo(row.path("safe").asText());assertThat(safe.valid()).as(name).isEqualTo(row.path("valid").asBoolean());assertThat(KnowledgeImportNames.sanitizeForLog(name)).as(name).isEqualTo(row.path("sanitized").asText());}}
    @Test void defaultImportAndExplicitOverridePathsPreserveGoDistinctGates()throws Exception{JsonNode empty=json.createObjectNode();assertThatThrownBy(()->config.resolveFileImport(empty,null,null,"PNG")).isInstanceOf(ApiException.class).hasMessage("上传图片文件需要设置VLM模型");assertThat(config.resolveFileImport(empty,empty,null,"PNG").path("enable_multimodel").asBoolean()).isFalse();assertThatThrownBy(()->config.resolveFileImport(empty,empty,null,"MP3")).isInstanceOf(ApiException.class).hasMessage("上传音频文件需要设置ASR语音识别模型");assertThatThrownBy(()->config.resolveFileImport(empty,null,null,"mp4")).isInstanceOf(ApiException.class).hasMessage("暂不支持上传视频文件");assertThatThrownBy(()->config.resolveFileImport(empty,null,null,"svg")).isInstanceOf(ApiException.class).hasMessage("不支持的文件类型: svg");assertThatThrownBy(()->config.resolveFileImport(empty,null,null,"unknown")).isInstanceOf(ApiException.class).hasMessage("无法确定文件类型");assertThat(config.resolveFileImport(empty,json.readTree("{\"enable_multimodel\":false}"),true,"txt").path("enable_multimodel").asBoolean()).isFalse();assertThat(config.resolveFileImport(empty,empty,true,"txt").path("enable_multimodel").asBoolean()).isTrue();}
    @Test void fullChunkSnapshotCanDisableParentChildWithoutMutatingKnowledgeBase()throws Exception{ObjectNode kb=(ObjectNode)json.readTree("{\"chunking_config\":{\"chunk_size\":512,\"chunk_overlap\":80,\"enable_parent_child\":true,\"languages\":[\"zh\"]}}");String before=kb.toString();ObjectNode effective=config.resolve(kb,json.readTree("{\"chunking_config\":{\"chunk_size\":128,\"chunk_overlap\":0}}"));assertThat(effective.path("chunking_config").path("enable_parent_child").asBoolean()).isFalse();assertThat(effective.path("chunking_config").path("chunk_overlap").asInt()).isEqualTo(80);((ArrayNode)effective.path("chunking_config").path("languages")).add("en");assertThat(kb.toString()).isEqualTo(before);assertThat(config.resolve(kb,null).path("chunking_config").path("languages").size()).isEqualTo(1);assertThatThrownBy(()->config.normalizeOverrides(json.readTree("{\"summary_enabled\":\"false\"}"))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->config.normalizeOverrides(json.readTree("[]"))).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->config.normalizeOverrides(json.readTree("{\"chunking_config\":42}"))).isInstanceOf(IllegalArgumentException.class);}
}
